  5	/** A worker heartbeat older than this means the worker is down. */
  6	export const WORKER_STALE_MS = 3_000;
  7	
  8	export interface JobRow {
  9	  seq: number;
 10	  id: string;
 11	  status: 'queued' | 'running' | 'completed' | 'failed';
 12	  input: string;
 13	  steps: number;
 14	  fail_attempts: number;
 15	  attempts: number;
 16	  completed: number;
 17	  result: string | null;
 18	  error: string | null;
 19	  idempotency_key: string | null;
 20	  next_run_at: number;
 21	  lease_until: number | null;
 22	  created_at: string;
 23	  updated_at: string;
 24	}
