 26	/** Opens the SQLite database shared by the server and worker processes, creating the schema if needed. */
 27	export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
 28	  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
 29	  const db = new DatabaseSync(path);
 30	  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
 31	  // open the same database at once, so the loser must wait rather than fail.
 32	  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL;');
 33	  db.exec(`
 34	    CREATE TABLE IF NOT EXISTS jobs (
 35	      seq INTEGER PRIMARY KEY AUTOINCREMENT,
 36	      id TEXT NOT NULL UNIQUE,
 37	      status TEXT NOT NULL,
 38	      input TEXT NOT NULL,
 39	      steps INTEGER NOT NULL,
 40	      fail_attempts INTEGER NOT NULL,
 41	      attempts INTEGER NOT NULL,
 42	      completed INTEGER NOT NULL,
 43	      result TEXT,
 44	      error TEXT,
 45	      idempotency_key TEXT UNIQUE,
 46	      next_run_at INTEGER NOT NULL,
 47	      lease_until INTEGER,
 48	      created_at TEXT NOT NULL,
 49	      updated_at TEXT NOT NULL
 50	    );
 51	    CREATE TABLE IF NOT EXISTS heartbeat (
 52	      name TEXT PRIMARY KEY,
 53	      ts INTEGER NOT NULL
 54	    );
 55	  `);
 56	  return db;
 57	}
 58	
 59	/** Maps a row to the public job JSON shape. */
 60	export function toJob(row: JobRow) {
 61	  return {
 62	    id: row.id,
 63	    status: row.status,
 64	    input: row.input,
 65	    steps: row.steps,
 66	    failAttempts: row.fail_attempts,
 67	    attempts: row.attempts,
 68	    progress: { completed: row.completed, total: row.steps },
 69	    result: row.status === 'completed' ? { output: row.result ?? '' } : null,
 70	    error: row.status === 'failed' ? row.error : null,
 71	    createdAt: row.created_at,
 72	    updatedAt: row.updated_at,
 73	  };
 74	}
  1	import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
  2	import { randomUUID } from 'node:crypto';
  3	import { readFileSync } from 'node:fs';
  4	import { openDatabase, toJob, WORKER_STALE_MS, type JobRow } from './db.ts';
  5	import { parseSubmission, type FieldError } from './validate.ts';
  6	
  7	const MAX_BODY_BYTES = 64 * 1024;
  8	
  9	const db = openDatabase();
 10	const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
 11	
 12	const selectById = db.prepare('SELECT * FROM jobs WHERE id = ?');
 13	const selectByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
 14	const selectAll = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
 15	const insertJob = db.prepare(`
 16	  INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, completed, idempotency_key, next_run_at, created_at, updated_at)
 17	  VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?, ?)
 18	`);
 19	const selectHeartbeat = db.prepare("SELECT ts FROM heartbeat WHERE name = 'worker'");
 20	
 21	const asRow = (x: unknown) => x as JobRow | undefined;
 22	
 23	function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
 24	  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...extraHeaders });
 25	  res.end(JSON.stringify(body));
 26	}
 27	
 28	function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
 29	  send(res, status, { error: fields ? { code, message, fields } : { code, message } });
 30	}
 31	
 32	function methodNotAllowed(res: ServerResponse, allow: string): void {
 33	  res.setHeader('Allow', allow);
 34	  sendError(res, 405, 'method_not_allowed', 'Method not allowed.');
 35	}
 36	
 37	function readBody(req: IncomingMessage): Promise<string | undefined> {
 38	  return new Promise((resolve, reject) => {
 39	    const chunks: Buffer[] = [];
 40	    let size = 0;
 41	    let tooLarge = false;
 42	    req.on('data', (chunk: Buffer) => {
 43	      size += chunk.length;
 44	      if (size > MAX_BODY_BYTES) tooLarge = true;
 45	      else chunks.push(chunk);
 46	    });
 47	    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
 48	    req.on('error', reject);
 49	  });
 50	}
 51	
 52	function health(res: ServerResponse): void {
 53	  const hb = selectHeartbeat.get() as { ts: number } | undefined;
 54	  const up = hb !== undefined && Date.now() - hb.ts <= WORKER_STALE_MS;
 55	  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
 56	}
 57	
 58	function listJobs(res: ServerResponse): void {
 59	  const rows = selectAll.all() as unknown as JobRow[];
 60	  send(res, 200, { jobs: rows.map(toJob) });
 61	}
 62	
 63	function getJob(res: ServerResponse, id: string): void {
 64	  const row = asRow(selectById.get(id));
 65	  if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
 66	  send(res, 200, toJob(row));
 67	}
 68	
 69	async function createJob(req: IncomingMessage, res: ServerResponse): Promise<void> {
 70	  const raw = await readBody(req);
 71	  const keyHeader = req.headers['idempotency-key'];
 72	  const parsed = parseSubmission(req.headers['content-type'], raw, keyHeader === undefined ? undefined : String(keyHeader));
 73	  if (!parsed.ok) return sendError(res, 400, 'invalid_request', 'The request is invalid.', parsed.fields);
 74	  const sub = parsed.value;
 75	
 76	  const now = new Date().toISOString();
 77	  db.exec('BEGIN IMMEDIATE');
 78	  try {
 79	    if (sub.idempotencyKey !== undefined) {
 80	      const existing = asRow(selectByKey.get(sub.idempotencyKey));
 81	      if (existing) {
 82	        db.exec('COMMIT');
 83	        if (existing.input === sub.input && existing.steps === sub.steps && existing.fail_attempts === sub.failAttempts) {
 84	          return send(res, 200, toJob(existing));
 85	        }
 86	        return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
 87	      }
 88	    }
 89	    const id = randomUUID();
 90	    insertJob.run(id, sub.input, sub.steps, sub.failAttempts, sub.idempotencyKey ?? null, Date.now(), now, now);
 91	    const row = asRow(selectById.get(id))!;
 92	    db.exec('COMMIT');
 93	    return send(res, 201, toJob(row));
 94	  } catch (err) {
 95	    db.exec('ROLLBACK');
 96	    throw err;
 97	  }
 98	}
 99	
100	function page(res: ServerResponse): void {
101	  res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
102	  res.end(uiHtml);
103	}
104	
105	function decodeId(raw: string): string {
106	  try {
107	    return decodeURIComponent(raw);
108	  } catch {
109	    return raw;
110	  }
111	}
112	
113	async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
114	  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
115	  const method = req.method ?? '';
116	
117	  if (pathname === '/health') return method === 'GET' ? health(res) : methodNotAllowed(res, 'GET');
118	  if (pathname === '/') return method === 'GET' ? page(res) : methodNotAllowed(res, 'GET');
119	  if (pathname === '/api/jobs') {
120	    if (method === 'GET') return listJobs(res);
121	    if (method === 'POST') return createJob(req, res);
122	    return methodNotAllowed(res, 'GET, POST');
123	  }
124	  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
125	  if (match) {
126	    if (method === 'GET') return getJob(res, decodeId(match[1]!));
127	    return methodNotAllowed(res, 'GET');
128	  }
129	  return sendError(res, 404, 'not_found', 'Not found.');
130	}
131	
132	const port = Number(process.env.PORT ?? 3000);
133	const server = createServer((req, res) => {
134	  handle(req, res).catch((err: unknown) => {
135	    console.error(err);
136	    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
137	    else res.end();
138	  });
139	});
140	
141	function shutdown(): void {
142	  server.close(() => {
143	    db.close();
144	    process.exit(0);
145	  });
146	  server.closeAllConnections();
147	  setTimeout(() => process.exit(0), 2_000).unref();
148	}
149	process.on('SIGTERM', shutdown);
150	process.on('SIGINT', shutdown);
151	
152	server.listen(port, () => console.log(`server listening on ${port}`));
  1	export interface FieldError {
  2	  field: string;
  3	  message: string;
  4	}
  5	
  6	export interface Submission {
  7	  input: string;
  8	  steps: number;
  9	  failAttempts: number;
 10	  idempotencyKey: string | undefined;
 11	}
 12	
 13	export type ParseResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };
 14	
 15	const FIELDS = new Set(['input', 'steps', 'failAttempts']);
 16	const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;
 17	
 18	const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
 19	
 20	function isIntIn(v: unknown, min: number, max: number): v is number {
 21	  return typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;
 22	}
 23	
 24	/**
 25	 * Validates a submission. `raw` is the body text (undefined when it exceeded the size limit);
 26	 * `idempotencyKey` is the Idempotency-Key header when present.
 27	 */
 28	export function parseSubmission(contentType: string | undefined, raw: string | undefined, idempotencyKey: string | undefined): ParseResult {
 29	  const bodyError = (message: string): ParseResult => ({ ok: false, fields: [{ field: 'body', message }] });
 30	
 31	  const mediaType = contentType?.split(';')[0]?.trim().toLowerCase();
 32	  if (mediaType !== 'application/json') return bodyError('Content-Type must be application/json');
 33	  if (raw === undefined) return bodyError('body is too large');
 34	
 35	  let parsed: unknown;
 36	  try {
 37	    parsed = JSON.parse(raw);
 38	  } catch {
 39	    return bodyError('body is not valid JSON');
 40	  }
 41	  if (!isPlainObject(parsed)) return bodyError('body must be a JSON object');
 42	
 43	  const fields: FieldError[] = [];
 44	  for (const key of Object.keys(parsed)) {
 45	    if (!FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
 46	  }
 47	
 48	  let input = '';
 49	  const rawInput = parsed.input;
 50	  if (typeof rawInput !== 'string') {
 51	    fields.push({ field: 'input', message: 'is required and must be a string' });
 52	  } else if (rawInput.length < 1 || rawInput.length > 1000) {
 53	    fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
 54	  } else if (rawInput.trim() === '') {
 55	    fields.push({ field: 'input', message: 'must not be blank' });
 56	  } else {
 57	    input = rawInput;
 58	  }
 59	
 60	  let steps = 5;
 61	  if (parsed.steps !== undefined) {
 62	    if (isIntIn(parsed.steps, 1, 20)) steps = parsed.steps;
 63	    else fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
 64	  }
 65	
 66	  let failAttempts = 0;
 67	  if (parsed.failAttempts !== undefined) {
 68	    if (isIntIn(parsed.failAttempts, 0, 5)) failAttempts = parsed.failAttempts;
 69	    else fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
 70	  }
 71	
 72	  if (idempotencyKey !== undefined && !KEY_RE.test(idempotencyKey)) {
 73	    fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
 74	  }
 75	
 76	  if (fields.length > 0) return { ok: false, fields };
 77	  return { ok: true, value: { input, steps, failAttempts, idempotencyKey } };
 78	}
  1	import { setTimeout as sleep } from 'node:timers/promises';
  2	import { openDatabase, type JobRow } from './db.ts';
  3	
  4	const STEP_MS = 100;
  5	/** A running job whose lease has expired (its worker died) is picked up again. */
  6	const LEASE_MS = 3_000;
  7	const RETRY_DELAY_MS = 500;
  8	const MAX_ATTEMPTS = 3;
  9	const IDLE_POLL_MS = 200;
 10	const HEARTBEAT_MS = 1_000;
 11	
 12	const db = openDatabase();
 13	
 14	const selectClaimable = db.prepare(`
 15	  SELECT * FROM jobs
 16	  WHERE (status = 'queued' AND next_run_at <= ?) OR (status = 'running' AND lease_until < ?)
 17	  ORDER BY seq ASC
 18	  LIMIT 1
 19	`);
 20	const claimJob = db.prepare(`
 21	  UPDATE jobs SET status = 'running', attempts = attempts + 1, completed = 0, lease_until = ?, updated_at = ?
 22	  WHERE id = ?
 23	`);
 24	const setProgress = db.prepare(`
 25	  UPDATE jobs SET completed = ?, lease_until = ?, updated_at = ? WHERE id = ? AND status = 'running'
 26	`);
 27	const completeJob = db.prepare(`
 28	  UPDATE jobs SET status = 'completed', completed = steps, result = ?, error = NULL, lease_until = NULL, updated_at = ?
 29	  WHERE id = ? AND status = 'running'
 30	`);
 31	const failJob = db.prepare(`
 32	  UPDATE jobs SET status = 'failed', result = NULL, error = 'transient failure', lease_until = NULL, updated_at = ?
 33	  WHERE id = ? AND status = 'running'
 34	`);
 35	const requeueJob = db.prepare(`
 36	  UPDATE jobs SET status = 'queued', completed = 0, next_run_at = ?, lease_until = NULL, updated_at = ?
 37	  WHERE id = ? AND status = 'running'
 38	`);
 39	const writeHeartbeat = db.prepare(`
 40	  INSERT INTO heartbeat (name, ts) VALUES ('worker', ?)
 41	  ON CONFLICT(name) DO UPDATE SET ts = excluded.ts
 42	`);
 43	
 44	interface Claimed {
 45	  id: string;
 46	  input: string;
 47	  steps: number;
 48	  failAttempts: number;
 49	  attempt: number;
 50	}
 51	
 52	let stopping = false;
 53	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
 54	  process.on(signal, () => {
 55	    stopping = true;
 56	  });
 57	}
 58	
 59	/** Takes the oldest runnable job and marks it running, in one transaction. */
 60	function claim(): Claimed | undefined {
 61	  const now = Date.now();
 62	  db.exec('BEGIN IMMEDIATE');
 63	  try {
 64	    const row = selectClaimable.get(now, now) as unknown as JobRow | undefined;
 65	    let claimed: Claimed | undefined;
 66	    if (row) {
 67	      claimJob.run(now + LEASE_MS, new Date(now).toISOString(), row.id);
 68	      claimed = {
 69	        id: row.id,
 70	        input: row.input,
 71	        steps: row.steps,
 72	        failAttempts: row.fail_attempts,
 73	        attempt: row.attempts + 1,
 74	      };
 75	    }
 76	    db.exec('COMMIT');
 77	    return claimed;
 78	  } catch (err) {
 79	    db.exec('ROLLBACK');
 80	    throw err;
 81	  }
 82	}
 83	
 84	async function runAttempt(job: Claimed): Promise<void> {
 85	  const iso = () => new Date().toISOString();
 86	
 87	  if (job.attempt <= job.failAttempts) {
 88	    if (job.attempt >= MAX_ATTEMPTS) failJob.run(iso(), job.id);
 89	    else requeueJob.run(Date.now() + RETRY_DELAY_MS, iso(), job.id);
 90	    return;
 91	  }
 92	
 93	  for (let step = 1; step <= job.steps; step++) {
 94	    if (stopping) {
 95	      // Graceful shutdown: hand the job back so the next worker can start it cleanly.
 96	      requeueJob.run(0, iso(), job.id);
 97	      return;
 98	    }
 99	    await sleep(STEP_MS);
100	    setProgress.run(step, Date.now() + LEASE_MS, iso(), job.id);
101	  }
102	  completeJob.run(job.input.toUpperCase(), iso(), job.id);
103	}
104	
105	function heartbeat(): void {
106	  writeHeartbeat.run(Date.now());
107	}
108	
109	heartbeat();
110	const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);
111	
112	console.log('worker started');
113	while (!stopping) {
114	  const job = claim();
115	  if (!job) {
116	    await sleep(IDLE_POLL_MS);
117	    continue;
118	  }
119	  try {
120	    await runAttempt(job);
121	  } catch (err) {
122	    console.error(`attempt for job ${job.id} failed:`, err);
123	    await sleep(IDLE_POLL_MS);
124	  }
125	}
126	
127	clearInterval(heartbeatTimer);
128	db.exec("DELETE FROM heartbeat WHERE name = 'worker'");
129	db.close();
130	console.log('worker stopped');
131	process.exit(0);
