 47	    const listEl = document.querySelector('[data-testid="job-list"]');
 48	    const items = new Map();
 49	
 50	    // Numeric text becomes a number; anything else is sent as-is so the API's validation reports it.
 51	    function toApiValue(text) {
 52	      const t = text.trim();
 53	      return /^[+-]?(\d+\.?\d*|\.\d+)([eE][+-]?\d+)?$/.test(t) ? Number(t) : text;
 54	    }
 55	
 56	    function showError(message) {
 57	      errorEl.textContent = message;
 58	    }
 59	
 60	    function describeRejection(body, status) {
 61	      const error = body && body.error;
 62	      if (!error) return 'Request failed (HTTP ' + status + ').';
 63	      const fields = Array.isArray(error.fields) && error.fields.length
 64	        ? ' ' + error.fields.map((f) => f.field + ': ' + f.message).join('; ') + '.'
 65	        : '';
 66	      return (error.message || error.code || 'Request failed.') + fields;
 67	    }
 68	
 69	    form.addEventListener('submit', async (event) => {
 70	      event.preventDefault();
 71	      showError('');
 72	      const payload = {
 73	        input: inputEl.value,
 74	        steps: toApiValue(stepsEl.value),
 75	        failAttempts: toApiValue(failEl.value),
 76	      };
 77	      try {
 78	        const res = await fetch('/api/jobs', {
 79	          method: 'POST',
 80	          headers: { 'content-type': 'application/json' },
 81	          body: JSON.stringify(payload),
 82	        });
 83	        const body = await res.json().catch(() => null);
 84	        if (res.ok) {
 85	          inputEl.value = '';
 86	          await refresh();
 87	        } else {
 88	          showError(describeRejection(body, res.status));
 89	        }
 90	      } catch (err) {
 91	        showError('Could not reach the server: ' + err.message);
 92	      }
 93	    });
 94	
 95	    function renderItem(job) {
 96	      let li = items.get(job.id);
 97	      if (!li) {
 98	        li = document.createElement('li');
 99	        li.dataset.testid = 'job-item';
100	        li.dataset.jobId = job.id;
101	        li.className = 'job-item';
102	        const meta = document.createElement('div');
103	        meta.className = 'job-meta';
104	        const status = document.createElement('span');
105	        status.dataset.testid = 'job-status';
106	        const progress = document.createElement('span');
107	        progress.dataset.testid = 'job-progress';
108	        const input = document.createElement('span');
109	        input.className = 'job-input';
110	        meta.append(status, progress, input);
111	        const result = document.createElement('div');
112	        result.dataset.testid = 'job-result';
113	        result.className = 'job-result';
114	        li.append(meta, result);
115	        items.set(job.id, li);
116	      }
117	      const [status, progress, input] = li.querySelector('.job-meta').children;
118	      const result = li.querySelector('[data-testid="job-result"]');
119	      status.textContent = job.status;
120	      progress.textContent = job.progress.completed + '/' + job.progress.total;
121	      input.textContent = job.input;
122	      if (job.status === 'completed') result.textContent = job.result.output;
123	      else if (job.status === 'failed') result.textContent = job.error;
124	      else result.textContent = '';
125	      return li;
126	    }
127	
128	    async function refresh() {
